def solution(n, s):
    if n == 0:
        return [] if s == 0 else None
    if s < n:
        return None
    result = [1] * n
    s -= n
    for i in range(n - 1, -1, -1):
        add = min(s, 9 - result[i])
        result[i] += add
        s -= add
        if s == 0:
            break
    return result if s == 0 else None

