    for expr in expressions:
        stack = []
        for char in expr:
            if char.isdigit():
                stack.append(char)
            elif char in '+-*/':
                b = stack.pop()
                a = stack.pop()
                if char == '+':
                    stack.append(str(int(a) + int(b)))
                elif char == '-':
                    stack.append(str(int(a) - int(b)))
