def solution(arr):
    def gcd(x, y):
        return x if y == 0 else gcd(y, x % y)

    def lcm(x, y):
        return x * y // gcd(x, y)

    def lcm_recursive(arr, index):
        if index == len(arr) - 1:
            return arr[index]
        return lcm(arr[index], lcm_recursive(arr, index + 1))

    return lcm_recursive(arr, 0)

def solution(sequence, k):
    left, current_sum, count = 0, 0, 0
    for right in range(len(sequence)):
        current_sum += sequence[right]
        while current_sum > k:
            current_sum -= sequence[left]
            left += 1
        if current_sum == k:
            count += 1
    return count

def solution(jobs):
    jobs.sort(key=lambda x: x[0])
    time, total_waiting_time, completed_jobs = 0, 0, 0
    while completed_jobs < len(jobs):
        available_jobs = [job for job in jobs if job[0] <= time and job not in completed_jobs]
        if available_jobs:
            job = min(available_jobs, key=lambda x: x[1])
            time += job[1]
            total_waiting_time += time - job[0]
            completed_jobs += 1
        else:
            time += 1
    return total_waiting_time // len(jobs)

def solution(N, road, K):
    import heapq
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v, w in road:
        graph[u].append((v, w))
        graph[v].append((u, w))

    distances = [float('inf')] * (N + 1)
    distances[1] = 0
    priority_queue = [(0, 1)]

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return sum(1 for d in distances[1:] if d <= K)

