def solution(want, number, discount):
    from collections import Counter
    want_count = Counter(dict(zip(want, number)))
    discount_count = Counter()
    valid_days = 0

    for i in range(len(discount)):
        discount_count[discount[i]] += 1

        if i >= 10:
            discount_count[discount[i - 10]] -= 1
            if discount_count[discount[i - 10]] == 0:
                del discount_count[discount[i - 10]]

        if i >= 9 and all(discount_count[item] >= want_count[item] for item in want_count):
            valid_days += 1

    return valid_days

