def solution(board):
    def check_winner(b):
        for row in b:
            if row.count('X') == 3:
                return True
        for col in range(3):
            if all(b[row][col] == 'X' for row in range(3)):
                return True
        if b[0][0] == b[1][1] == b[2][2] == 'X' or b[0][2] == b[1][1] == b[2][0] == 'X':
            return True
        return False

    x_count = sum(row.count('X') for row in board)
    o_count = sum(row.count('O') for row in board)

    if x_count < o_count or x_count > o_count + 1:
        return 0
    if check_winner(board) and x_count == o_count:
        return 0
    if check_winner(board) and x_count > o_count:
        return 0
    return 1

